    pub async fn avg_id(self) -> anyhow::Result<Option<f64>> {
        let values = self.pluck_id().await?;
        let mut sum = 0.0_f64;
        let mut count = 0u64;
        for value in values.into_iter() {
            sum += value as f64;
            count += 1;
        }
        if count == 0 {
            Ok(None)
        } else {
            Ok(Some(sum / count as f64))
        }
    }

